/**
 * Generic compact public wrapper shape for Redis-bridged websocket outputs. Prefer concrete websocket event schemas for known events. Realtime producers use stream-family Redis channels such as ws:symbol-price-events, ws:account-summary-events, ws:account-checklist-events, ws:orders-counts-events, ws:orders-page-events, ws:orders-lifecycle-events, ws:notification-events, and ws:channel-events.
 */
export type WebSocketRedisBridgeEvent = {
    /**
     * Event payload forwarded to the user room unchanged. Use the concrete event-specific schema that matches the `event` field.
     */
    data?: WebSocketEconomicCalendarSnapshot | WebSocketEconomicGuardSnapshot | WebSocketEconomicSettingsSnapshot | WebSocketSymbolPriceEvent | WebSocketSymbolSpecsEvent | WebSocketNotificationCreatedEvent | WebSocketTelegramCatalogUpdatedEvent;
    /**
     * Compact public event name emitted to Socket.IO clients. Channel families isolate high-frequency prices from account/order/notification/channel refresh work.
     */
    event?: 'economic-calendar:snapshot' | 'economic-news-guard:snapshot' | 'economic-news-settings:snapshot' | 'spt' | 'ssx' | 'dn' | 'telegram:catalog-updated';
};

