export type WebSocketTradeOrderView = {
    accountNumber?: string | null;
    accountPlatform?: string | null;
    /**
     * Broker-reported open/fill price for active open orders. Falls back to entryPrice only when the order is confirmed open and no separate broker fill diagnostic exists.
     */
    brokerOpenPrice?: number | null;
    /**
     * TradeBrokerPartialClose id for synthetic broker-side manual partial-close rows.
     */
    brokerPartialCloseId?: string | null;
    /**
     * Net broker PnL for terminal closed orders: profit plus commission and swap.
     */
    brokerPnl?: number | null;
    channelPhotoUrl?: string | null;
    channelTitle?: string | null;
    channelUsername?: string | null;
    /**
     * Broker-reported close price for terminal closed orders.
     */
    closePrice?: number | null;
    /**
     * Terminal close reason. Manual closes can be upgraded to TP only when strict TP completion is confirmed from executable TP slices. Break-even and trailing-stop closes are broker stop closes with more specific context when available.
     */
    closeReason?: 'SL' | 'TP' | 'BREAKEVEN' | 'TRAILING_STOP' | 'MANUAL';
    closeTime?: Date | null;
    /**
     * Authoritative TP level for terminal TP closes, for example TP2 => 2.
     */
    closeTpLevel?: number | null;
    commission?: number | null;
    /**
     * Broker symbol contract size for active open orders. Omitted for pending and closed order rows.
     */
    contractSize?: number | null;
    createdAt?: Date | null;
    /**
     * Current displayed price. Active open order responses may use a best-effort fresh broker close-side quote (BUY uses bid, SELL uses ask) without persisting it; terminal closed orders use the broker close price.
     */
    currentPrice?: number | null;
    entryPrice?: number | null;
    /**
     * Milliseconds from signal arrival to successful order placement/opening. Present only for orders created from an executed signal when timing is available.
     */
    executionDelayMs?: number | null;
    id?: string;
    /**
     * True for live mirrored broker orders that are outside Tragram and therefore do not have a Tragram trade id.
     */
    isExternal?: boolean;
    marketHours?: WebSocketTradeMarketHours | null;
    mtAccountId?: string | null;
    netProfit?: number | null;
    openTime?: Date | null;
    orderId?: string | null;
    orderType?: string;
    /**
     * Parent trade id for synthetic partial-close rows.
     */
    parentTradeId?: string | null;
    /**
     * Symbol precision used to render broker-style prices.
     */
    priceDigits?: number | null;
    profit?: number | null;
    /**
     * Present when the row is a synthetic closed-order record for a successful TP partial close or broker-side manual partial close.
     */
    recordType?: 'TP_PARTIAL_CLOSE' | 'BROKER_PARTIAL_CLOSE';
    side?: string;
    signalId?: string | null;
    status?: 'open' | 'pending' | 'closed';
    stopLoss?: number | null;
    swap?: number | null;
    symbol?: string;
    /**
     * Effective per-level TP execution progress for the trade. NOT_ALLOCATED means the target was present in the source TP ladder but has no executable lot allocation under this trade plan.
     */
    takeProfitTargets?: Array<WebSocketTradeTakeProfitTarget>;
    ticketId?: string | null;
    /**
     * TradeTpExecution id for synthetic TP partial-close rows.
     */
    tpExecutionId?: string | null;
    /**
     * TradeTpSlice id for synthetic TP partial-close rows.
     */
    tpSliceId?: string | null;
    updatedAt?: Date | null;
    userId?: string | null;
    /**
     * Effective lots size. Active trades expose live remaining lots; terminal trades expose the pre-close lots.
     */
    volume?: number;
};

